(function(){window.PhysicaRankPyqNeet_chemistry_aldehydesketonesandcarboxylicacids=[{id:"neet-2026-q050",pn:50,y:"NEET 2026 \xB7 21 Jun \xB7 Re-exam",tp:"Aldehydes, Ketones and Carboxylic Acids",st:"Aldol condensation products",q:`The compound that CANNOT be obtained from the aldol condensation reaction shown below, is
2,2-dimethylcyclopentanone + PhCHO (NaOH, \u0394) \u2192`,o:["2,2-dimethylcyclopentanone with =CH\u2013Ph on the alpha carbon","two 2,2-dimethylcyclopentanone units joined by a C=C between their alpha carbons (alkylidene)","2,2-dimethylcyclopentanone with =CH\u2013Ph at the alpha carbon (drawn without the E/Z bond detail)","2,2-dimethylcyclopentanone linked by a single bond from its alpha carbon to a cyclopentene ring carrying gem-dimethyl"],c:3,s:`The ketone has alpha hydrogens on one side only (the other alpha carbon is C(CH\u2083)\u2082).
With PhCHO it gives the alpha,beta-unsaturated ketone =CH\u2013Ph (E and Z isomers) and water.
It can also react with another molecule of the ketone to give the C=C linked dimer (alpha,beta-unsaturated carbonyl).
Option 4 has a single bond to a cyclopentene ring, which cannot form by this reaction.
Note: Publisher solution text says 'compound 2 cannot be obtained', but its own drawn product matches option 2 (obtainable); printed answer is (4), kept. Option texts are my descriptions of drawn structures.`,fig:{w:360,h:240,alt:"Reaction: 2,2-dimethylcyclopentanone + PhCHO with NaOH, \u0394. Options: (1) the ketone with =CH\u2013Ph on its other alpha carbon; (2) the ketone joined by a C=C to a second ring carrying H\u2083C and CH\u2083; (3) the ketone with =CH\u2013Ph, Ph drawn upward; (4) the ketone joined by a single bond to a cyclopentene ring carrying H\u2083C and CH\u2083.",d:[["p","M60.0 27.0 L72.4 36.0 L67.6 50.5 L52.4 50.5 L47.6 36.0 Z"],["l",60,27,60,14],["l",63,26,63,15],["t",61.5,11,"O","ms"],["l",47.6,36,35.6,28],["l",47.6,36,35.6,44],["t",34.6,28,"H\u2083C","es"],["t",34.6,49,"H\u2083C","es"],["t",92,48,"+ PhCHO"],["l",150,44,200,44,"a"],["t",175,38,"NaOH, \u0394","ms"],["p","M80.0 99.0 L92.4 108.0 L87.6 122.5 L72.4 122.5 L67.6 108.0 Z"],["l",80,99,80,86],["l",83,98,83,87],["t",81.5,83,"O","ms"],["l",67.6,108,55.6,100],["l",67.6,108,55.6,116],["t",54.6,100,"H\u2083C","es"],["t",54.6,121,"H\u2083C","es"],["t",4,116,"(1)"],["l",92.4,108,106.4,102],["l",95.2,110,105.9,105.5],["l",106.4,102,116.4,102],["t",118.4,106,"Ph"],["p","M250.0 99.0 L262.4 108.0 L257.6 122.5 L242.4 122.5 L237.6 108.0 Z"],["l",250,99,250,86],["l",253,98,253,87],["t",251.5,83,"O","ms"],["l",237.6,108,225.6,100],["l",237.6,108,225.6,116],["t",224.6,100,"H\u2083C","es"],["t",224.6,121,"H\u2083C","es"],["t",174,116,"(2)"],["l",262.4,108,276.4,108],["l",264,105,274.7,105],["p","M276.4 108.0 L285.3 95.6 L299.9 100.3 L299.9 115.6 L285.3 120.3 Z"],["l",285.3,120.3,276.3,131.3],["l",285.3,120.3,294.3,131.3],["t",275.3,141.3,"H\u2083C","ms"],["t",297.3,141.3,"CH\u2083","ms"],["p","M80.0 177.0 L92.4 186.0 L87.6 200.5 L72.4 200.5 L67.6 186.0 Z"],["l",80,177,80,164],["l",83,176,83,165],["t",81.5,161,"O","ms"],["l",67.6,186,55.6,178],["l",67.6,186,55.6,194],["t",54.6,178,"H\u2083C","es"],["t",54.6,199,"H\u2083C","es"],["t",4,194,"(3)"],["l",92.4,186,106.4,190],["l",94.9,183.6,105.5,186.6],["l",106.4,190,108.4,176],["t",104.4,173,"Ph"],["p","M250.0 177.0 L262.4 186.0 L257.6 200.5 L242.4 200.5 L237.6 186.0 Z"],["l",250,177,250,164],["l",253,176,253,165],["t",251.5,161,"O","ms"],["l",237.6,186,225.6,178],["l",237.6,186,225.6,194],["t",224.6,178,"H\u2083C","es"],["t",224.6,199,"H\u2083C","es"],["t",174,194,"(4)"],["l",262.4,186,276.4,186],["p","M276.4 186.0 L285.3 173.6 L299.9 178.3 L299.9 193.6 L285.3 198.3 Z"],["l",279.6,186,286.4,176.7],["l",285.3,198.3,276.3,209.3],["l",285.3,198.3,294.3,209.3],["t",275.3,219.3,"H\u2083C","ms"],["t",297.3,219.3,"CH\u2083","ms"]]},sfig:{w:360,h:296,alt:"Two reactions with dil. NaOH, \u0394: the ketone (two \u03B1-H shown) + O=CH\u2013Ph gives H\u2082O + the =CH\u2013Ph product (E + Z isomers); the ketone + a second ketone molecule gives the ring=ring \u03B1,\u03B2-unsaturated carbonyl compound.",d:[["p","M50.0 27.0 L62.4 36.0 L57.6 50.5 L42.4 50.5 L37.6 36.0 Z"],["l",50,27,50,14],["l",53,26,53,15],["t",51.5,11,"O","ms"],["l",37.6,36,25.6,28],["l",37.6,36,25.6,44],["l",62.4,36,70.4,29],["t",71.4,29,"H","s"],["l",62.4,36,70.4,43],["t",71.4,50,"H","s"],["t",82,46,"+"],["t",100,46,"O","m"],["l",106,40,116,40],["l",106,44,116,44],["t",121,46,"C","m"],["l",126,38,136,30],["t",138,30,"Ph","s"],["l",126,46,136,54],["t",138,62,"H","s"],["l",158,42,212,42,"a"],["t",185,35,"dil. NaOH","ms"],["t",185,57,"\u0394","ms"],["t",220,46,"H\u2082O +"],["p","M250.0 83.0 L262.4 92.0 L257.6 106.5 L242.4 106.5 L237.6 92.0 Z"],["l",250,83,250,70],["l",253,82,253,71],["t",251.5,67,"O","ms"],["l",237.6,92,225.6,84],["l",237.6,92,225.6,100],["l",262.4,92,275.4,92],["l",263.9,89,273.8,89],["t",277.4,96,"CH\u2013Ph"],["t",250,130,"(E + Z isomers)","ms"],["p","M50.0 161.0 L62.4 170.0 L57.6 184.5 L42.4 184.5 L37.6 170.0 Z"],["l",50,161,50,148],["l",53,160,53,149],["t",51.5,145,"O","ms"],["l",37.6,170,25.6,162],["l",37.6,170,25.6,178],["l",62.4,170,70.4,163],["t",71.4,163,"H","s"],["l",62.4,170,70.4,177],["t",71.4,184,"H","s"],["t",82,180,"+"],["t",100,180,"O","m"],["l",106,174,118,174],["l",106,178,118,178],["p","M118.0 176.0 L127.0 163.6 L141.5 168.4 L141.5 183.6 L127.0 188.4 Z"],["l",127,188.4,118,199.4],["l",127,188.4,136,199.4],["l",170,176,230,176,"a"],["t",200,169,"dil. NaOH","ms"],["t",200,191,"\u0394","ms"],["p","M150.0 227.0 L162.4 236.0 L157.6 250.5 L142.4 250.5 L137.6 236.0 Z"],["l",150,227,150,214],["l",153,226,153,215],["t",151.5,211,"O","ms"],["l",137.6,236,125.6,228],["l",137.6,236,125.6,244],["l",162.4,236,176.4,236],["l",164,233,174.7,233],["p","M176.4 236.0 L185.3 223.6 L199.9 228.3 L199.9 243.6 L185.3 248.3 Z"],["l",185.3,248.3,176.3,259.3],["l",185.3,248.3,194.3,259.3],["t",175,286,"\u03B1, \u03B2-unsaturated carbonyl compound","ms"]]}},{id:"neet-2026-q055",pn:55,y:"NEET 2026 \xB7 21 Jun \xB7 Re-exam",tp:"Aldehydes, Ketones and Carboxylic Acids",st:"Haloform reaction",q:`For the following reaction sequence, choose the correct option
Benzene \u2192 (i. CH\u2083COCl, AlCl\u2083; ii. NaOCl) \u2192 P + Q`,o:["P and Q are aromatic compounds","If P gives a carboxylic acid on acidification, Q gives a poisonous gas on exposure to air and light","Both P and Q are carbonyl compounds","If P is the sodium salt of a carboxylic acid, Q is a primary alcohol"],c:1,s:`Benzene + CH\u2083COCl with AlCl\u2083 gives acetophenone (C\u2086H\u2085COCH\u2083).
NaOCl does the haloform reaction: P = sodium benzoate (C\u2086H\u2085COO\u207BNa\u207A), Q = CHCl\u2083 (chloroform).
Acidifying P gives benzoic acid.
Chloroform in air and light is oxidised: 2CHCl\u2083 + O\u2082 \u2192 2COCl\u2082 + 2HCl.
COCl\u2082 is phosgene, a poisonous gas.`,sfig:{w:270,h:282,alt:"Scheme: benzene + CH\u2083COCl (AlCl\u2083) gives acetophenone; acetophenone with NaOCl gives sodium benzoate (P) + CHCl\u2083 (Q); P on acidic hydrolysis gives benzoic acid; 2CHCl\u2083 + O\u2082 in air and light gives 2COCl\u2082 + 2HCl, phosgene gas (poisonous gas).",d:[["p","M30.0 27.0 L41.3 33.5 L41.3 46.5 L30.0 53.0 L18.7 46.5 L18.7 33.5 Z"],["c",30,40,7.15],["t",50,44,"+ CH\u2083COCl","s"],["l",108,40,168,40,"a"],["t",138,33,"AlCl\u2083","ms"],["p","M196.0 33.0 L207.3 39.5 L207.3 52.5 L196.0 59.0 L184.7 52.5 L184.7 39.5 Z"],["c",196,46,7.15],["l",196,33,196,22],["t",196,17,"COCH\u2083","ms"],["p","M30.0 103.0 L41.3 109.5 L41.3 122.5 L30.0 129.0 L18.7 122.5 L18.7 109.5 Z"],["c",30,116,7.15],["l",30,103,30,92],["t",30,87,"COCH\u2083","ms"],["l",76,112,136,112,"a"],["t",106,105,"NaOCl","ms"],["p","M170.0 103.0 L181.3 109.5 L181.3 122.5 L170.0 129.0 L158.7 122.5 L158.7 109.5 Z"],["c",170,116,7.15],["l",170,103,170,92],["t",170,87,"COO\u207BNa\u207A","ms"],["t",198,120,"+ CHCl\u2083","s"],["t",170,146,"(P)","ms"],["t",216,146,"(Q)","ms"],["p","M30.0 179.0 L41.3 185.5 L41.3 198.5 L30.0 205.0 L18.7 198.5 L18.7 185.5 Z"],["c",30,192,7.15],["l",30,179,30,168],["t",30,163,"COO\u207BNa\u207A","ms"],["t",30,222,"(P)","ms"],["l",66,192,166,192,"a"],["t",116,185,"Acidic Hydrolysis","ms"],["p","M196.0 179.0 L207.3 185.5 L207.3 198.5 L196.0 205.0 L184.7 198.5 L184.7 185.5 Z"],["c",196,192,7.15],["l",196,179,196,168],["t",196,163,"COOH","ms"],["t",30,248,"2CHCl\u2083 + O\u2082","ms"],["t",30,262,"(Q)","ms"],["l",80,246,140,246,"a"],["t",110,239,"In air","ms"],["t",110,261,"Light","ms"],["t",200,250,"2COCl\u2082 + 2HCl","ms"],["t",200,263,"Phosgene gas","ms"],["t",200,275,"(poisonous gas)","ms"]]}},{id:"neet-2026-q079",pn:79,y:"NEET 2026 \xB7 21 Jun \xB7 Re-exam",tp:"Aldehydes, Ketones and Carboxylic Acids",st:"Etard reaction",q:`Consider the following reaction, and choose the correct option.
toluene \u2192 P  (i. CrO\u2082Cl\u2082, CS\u2082; ii. H\u2083O\u207A)`,o:["Compound P can be prepared by treating benzene with anhydrous AlCl\u2083 and CH\u2083COCl","On treatment with bromine water, compound P gives a white precipitate","Compound P is obtained by the hydrogenation of benzoyl chloride with Pd on BaSO\u2084","On treating compound P with saturated NaHCO\u2083 solution, brisk effervescence is observed"],c:2,s:`Toluene with CrO\u2082Cl\u2082 in CS\u2082 gives a chromium complex, C\u2086H\u2085CH(OCrOHCl\u2082)\u2082 (Etard reaction).
Hydrolysis with H\u2083O\u207A gives benzaldehyde, C\u2086H\u2085CHO. So P is benzaldehyde.
Benzoyl chloride with H\u2082 over Pd-BaSO\u2084 gives benzaldehyde (Rosenmund reaction).
Benzene with CH\u2083COCl and anhydrous AlCl\u2083 gives acetophenone, not P.`,sfig:{w:330,h:345,alt:"Toluene with CrO\u2082Cl\u2082, CS\u2082 gives C\u2086H\u2085CH(OCrOHCl\u2082)\u2082, which with H\u2083O\u207A gives benzaldehyde; benzoyl chloride with H\u2082, Pd-BaSO\u2084 gives benzaldehyde (Rosenmund reaction); benzene with CH\u2083COCl, anhydrous AlCl\u2083 gives acetophenone.",d:[["p","M40.0 42.0 L53.9 50.0 L53.9 66.0 L40.0 74.0 L26.1 66.0 L26.1 50.0 Z",""],["l",40,46.5,50,52.2,""],["l",50,63.8,40,69.5,""],["l",30,63.8,30,52.2,""],["l",40,42,40,34,""],["t",40,31,"CH\u2083","m"],["l",66,58,150,58,"a"],["t",108,50,"CrO\u2082Cl\u2082, CS\u2082","ms"],["p","M180.0 42.0 L193.9 50.0 L193.9 66.0 L180.0 74.0 L166.1 66.0 L166.1 50.0 Z",""],["l",180,46.5,190,52.2,""],["l",190,63.8,180,69.5,""],["l",170,63.8,170,52.2,""],["l",180,42,180,34,""],["t",180,31,"CH(OCrOHCl\u2082)\u2082","m"],["l",180,80,180,118,"a"],["t",186,103,"H\u2083O\u207A","s"],["p","M180.0 144.0 L193.9 152.0 L193.9 168.0 L180.0 176.0 L166.1 168.0 L166.1 152.0 Z",""],["l",180,148.5,190,154.2,""],["l",190,165.8,180,171.5,""],["l",170,165.8,170,154.2,""],["l",180,144,180,136,""],["t",180,133,"CHO","m"],["t",8,236,"Compound P is obtained by","s"],["p","M160.0 216.0 L173.9 224.0 L173.9 240.0 L160.0 248.0 L146.1 240.0 L146.1 224.0 Z",""],["l",160,220.5,170,226.2,""],["l",170,237.8,160,243.5,""],["l",150,237.8,150,226.2,""],["l",160,216,160,208,""],["t",160,205,"COCl","m"],["l",184,232,262,232,"a"],["t",223,226,"H\u2082","ms"],["t",223,245,"Pd-BaSO\u2084","ms"],["p","M290.0 216.0 L303.9 224.0 L303.9 240.0 L290.0 248.0 L276.1 240.0 L276.1 224.0 Z",""],["l",290,220.5,300,226.2,""],["l",300,237.8,290,243.5,""],["l",280,237.8,280,226.2,""],["l",290,216,290,208,""],["t",290,205,"CHO","m"],["t",290,262,"Rosenmund","ms"],["t",290,273,"reaction","ms"],["p","M40.0 302.0 L53.9 310.0 L53.9 326.0 L40.0 334.0 L26.1 326.0 L26.1 310.0 Z",""],["l",40,306.5,50,312.2,""],["l",50,323.8,40,329.5,""],["l",30,323.8,30,312.2,""],["l",62,318,152,318,"a"],["t",105,310,"CH\u2083COCl, Anhy.","ms"],["t",107,331,"AlCl\u2083","ms"],["p","M180.0 302.0 L193.9 310.0 L193.9 326.0 L180.0 334.0 L166.1 326.0 L166.1 310.0 Z",""],["l",180,306.5,190,312.2,""],["l",190,323.8,180,329.5,""],["l",170,323.8,170,312.2,""],["l",180,302,180,294,""],["t",180,291,"COCH\u2083","m"]]}}]})();
